{
  "name": "RIC温度控制器",
  "name_en": "RIC Temperature Controller",
  "manufacturer": "",
  "description": "用于实验中温度设定、温度读取与设备状态查询的温控仪器。该接口还支持空闲模式、版本查询、调试输出以及发送原始命令，适合将温度控制集成到自动化实验流程中。",
  "description_en": "A temperature-control instrument used in laboratory workflows for setting temperature, reading back temperature, and checking device status. The interface also supports idle mode, version queries, debug output, and raw command execution for integration into automated experiments.",
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开与RIC设备的连接。",
      "description_en": "Open the connection to the RIC device."
    },
    {
      "action_name": "auto-setdebug",
      "description": "启用或设置调试输出。",
      "description_en": "Enable or configure debug output."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与RIC设备的连接。",
      "description_en": "Close the connection to the RIC device."
    },
    {
      "action_name": "auto-execute",
      "description": "向设备发送原始命令并执行。",
      "description_en": "Send and execute a raw command on the device."
    },
    {
      "action_name": "auto-gettemp",
      "description": "读取当前温度。",
      "description_en": "Read the current temperature."
    },
    {
      "action_name": "auto-settemp",
      "description": "设置目标温度。",
      "description_en": "Set the target temperature."
    },
    {
      "action_name": "auto-idle",
      "description": "将设备切换到空闲状态。",
      "description_en": "Put the device into an idle state."
    },
    {
      "action_name": "auto-version",
      "description": "查询设备版本信息。",
      "description_en": "Query the device version information."
    },
    {
      "action_name": "auto-status",
      "description": "查询设备当前状态。",
      "description_en": "Query the current device status."
    }
  ],
  "tag_hints": [
    "temperature control",
    "temperature setpoint",
    "temperature readback",
    "instrument status",
    "idle mode",
    "raw command interface"
  ]
}

